1	<?php
2	
3	namespace App\Notifications;
4	
5	use App\Models\AwardRedeem;
6	use App\Models\User;
7	use Illuminate\Bus\Queueable;
8	use Illuminate\Contracts\Queue\ShouldQueue;
9	use Illuminate\Notifications\Messages\MailMessage;
10	use Illuminate\Notifications\Notification;
11	use Illuminate\Support\HtmlString;
12	
13	/**
14	 * Notification for award request.
15	 * This notification is sent to users when they make a request for an award.
16	 */
17	class AwardRedeemCreated extends Notification implements ShouldQueue
18	{
19	    use Queueable;
20	    use DefaultQueueConfiguration;
21	
22	
23	    public AwardRedeem $awardRedeem;
24	
25	    /**
26	     * @param AwardRedeem $awardRedeem the award request
27	     */
28	    public function __construct(AwardRedeem $awardRedeem)
29	    {
30	        $this->awardRedeem = $awardRedeem;
31	
32	    }
33	
34	
35	    /**
36	     * Get the notification's delivery channels.
37	     *
38	     * @return array<int, string>
39	     */
40	    public function via(object $notifiable): array
41	    {
42	        return ['mail', 'database'];
43	    }
44	
45	    /**
46	     * Build the message.
47	     * @param object&User $notifiable
48	     */
49	    public function toMail(object $notifiable): MailMessage
50	    {
51	        return (new MailMessage())
52	            ->greeting('Hai richiesto un premio.')
53	            ->subject('Conferma richiesta premio')
54	            ->line(new HtmlString(
55	                '<p>Ti informiamo che la richiesta di riscatto premio è stata registrata correttamente.</p>
56	                <p>Riceverai il tuo premio all\'indirizzo che hai indicato ed entro i tempi previsti nella "norme di partecipazione".</p>
57	                <p>Siamo felici che ti sei divertito assieme a noi! <br>Continua a partecipare, ti aspettano sempre nuove missioni e tante ricette da cui prendere ispirazione.</p>
58	                '
59	            ))
60	            ->action(
61	                'Partecipa a nuove missioni',
62	                route('missioni_'.$notifiable->preferredLocale())
63	            )
64	        ;
65	
66	    }
67	
68	    /**
69	     * Get the array representation of the notification.
70	     * @param object&User $notifiable
71	     * @return array<string, mixed>
72	     */
73	    public function toArray(object $notifiable): array
74	    {
75	        return [
76	            //
77	            'mail_html' => $this->toMail($notifiable)->render(),
78	            'award_redeem_id' => $this->awardRedeem->id,
79	        ];
80	    }
81	
82	}
83
